with cleaned as (select *, trim(channel) as clean_channel, coalesce(channel, 'UNKNOWN') as resolved_channel from orders where order_date >= to_date('2023-03-02') and channel is distinct from 'store') select id, store_id, metric, value from (select id, store_id, shipping_fee, discount, amount from cleaned) src unpivot (value for metric in (shipping_fee as SHIPPING_FEE, discount as DISCOUNT, amount as AMOUNT_VAL))
